// AP Multi-level Agricultural Location Database
// Structure: State -> District -> Mandals -> Villages

export interface APLocationData {
  districts: {
    [districtName: string]: {
      english: string;
      places: string[]; // Mandals / Towns / Cities in the district
      villages: string[]; // Generic local villages for cascading simulation
      mandalVillages?: { [mandalName: string]: string[] }; // Mandal-specific villages
    };
  };
}

