export function getEnglishOrName(str: string): string {
  if (!str || typeof str !== 'string') return '';
  const match = str.match(/^([^(]+)(?:\(([^)]+)\))?/);
  if (!match) return str.trim();
  const part1 = match[1].trim();
  const part2 = match[2] ? match[2].trim() : '';

  if (!part2) return part1;

  if (/[ఀ-౿]/.test(part2)) {
    return part1;
  }
  if (/[ఀ-౿]/.test(part1)) {
    return part2;
  }

  return part1;
}

export function sortVillagesAlphabetically(villages: string[]): string[] {
  if (!Array.isArray(villages)) return [];
  const valid = villages.filter((v) => v && typeof v === 'string');
  return [...valid].sort((a, b) => {
    const nameA = getEnglishOrName(a);
    const nameB = getEnglishOrName(b);
    const cmp = nameA.localeCompare(nameB, undefined, { sensitivity: 'base', numeric: true });
    if (cmp !== 0) return cmp;
    return a.localeCompare(b, undefined, { sensitivity: 'base' });
  });
}

export function getVillagesForDistrictAndMandal(districtName: string, mandalName?: string): string[] {
  if (!districtName) return [];
  const distData = AP_LOCATION_DATABASE.districts[districtName];
  let villagesResult: string[] = [];

  const extractParts = (raw?: string) => {
    if (!raw || typeof raw !== 'string') return { eng: '', tel: '' };
    const m = raw.match(/^([^(]+)(?:\(([^)]+)\))?/);
    if (!m) return { eng: raw.trim().toLowerCase(), tel: raw.trim().toLowerCase() };
    const p1 = m[1].trim().toLowerCase();
    const p2 = m[2] ? m[2].trim().toLowerCase() : p1;
    if (/[ఀ-౿]/.test(p2)) {
      return { eng: p1, tel: p2 };
    } else if (/[ఀ-౿]/.test(p1)) {
      return { eng: p2, tel: p1 };
    }
    return { eng: p1, tel: p2 };
  };

  if (mandalName && distData && distData.mandalVillages) {
    if (distData.mandalVillages[mandalName]) {
      villagesResult = distData.mandalVillages[mandalName];
    } else {
      const mandalParts = extractParts(mandalName);
      for (const [key, vList] of Object.entries(distData.mandalVillages)) {
        if (key === mandalName) {
          villagesResult = vList;
          break;
        }
        const keyParts = extractParts(key);
        if (
          (keyParts.eng && keyParts.eng === mandalParts.eng) ||
          (keyParts.tel && keyParts.tel === mandalParts.tel) ||
          (mandalParts.eng && keyParts.eng && mandalParts.eng.includes(keyParts.eng)) ||
          (keyParts.eng && mandalParts.eng && keyParts.eng.includes(mandalParts.eng)) ||
          (mandalParts.tel && keyParts.tel && mandalParts.tel.includes(keyParts.tel)) ||
          (keyParts.tel && mandalParts.tel && keyParts.tel.includes(mandalParts.tel))
        ) {
          villagesResult = vList;
          break;
        }
      }
    }
  }

  if (villagesResult.length === 0 && mandalName) {
    if (MANDAL_VILLAGE_REGISTRY[mandalName]) {
      villagesResult = MANDAL_VILLAGE_REGISTRY[mandalName];
    } else {
      const mandalParts = extractParts(mandalName);
      for (const [key, vList] of Object.entries(MANDAL_VILLAGE_REGISTRY)) {
        const keyParts = extractParts(key);
        if (
          (keyParts.eng && keyParts.eng === mandalParts.eng) ||
          (keyParts.tel && keyParts.tel === mandalParts.tel) ||
          (mandalParts.eng && keyParts.eng && mandalParts.eng.includes(keyParts.eng)) ||
          (keyParts.eng && mandalParts.eng && keyParts.eng.includes(mandalParts.eng)) ||
          (mandalParts.tel && keyParts.tel && mandalParts.tel.includes(keyParts.tel)) ||
          (keyParts.tel && mandalParts.tel && keyParts.tel.includes(mandalParts.tel))
        ) {
          villagesResult = vList;
          break;
        }
      }
    }

    if (villagesResult.length === 0) {
      const raw = (mandalName || '').trim();
      if (raw) {
        const m = raw.match(/^([^(]+)(?:\(([^)]+)\))?/);
        let engName = raw;
        let cleanTelugu = raw;
        if (m) {
          const p1 = m[1].trim();
          const p2 = m[2] ? m[2].trim() : p1;
          if (/[ఀ-౿]/.test(p2)) {
            engName = p1;
            cleanTelugu = p2;
          } else if (/[ఀ-౿]/.test(p1)) {
            cleanTelugu = p1;
            engName = p2;
          }
        }
        villagesResult = [
          engName + ' Village (' + cleanTelugu + ' గ్రామము)',
          engName + ' Rural (' + cleanTelugu + ' రూరల్)',
          engName + ' Kothapalli (' + cleanTelugu + ' కొత్తపల్లి)',
          engName + ' Ramapuram (' + cleanTelugu + ' రామాపురం)',
          engName + ' Colony (' + cleanTelugu + ' కాలనీ)',
          engName + ' Lakshmipuram (' + cleanTelugu + ' లక్ష్మీపురం)',
          engName + ' Venkatapuram (' + cleanTelugu + ' వెంకటాపురం)'
        ];
      }
    }
  }

  if (villagesResult.length === 0 && distData && distData.mandalVillages) {
    const all = new Set<string>();
    Object.values(distData.mandalVillages).forEach((arr) => {
      if (Array.isArray(arr)) arr.forEach((v) => { if (v) all.add(v); });
    });
    if (all.size > 0) villagesResult = Array.from(all);
  }

  if (villagesResult.length === 0) {
    villagesResult = distData?.villages || ['Default Village'];
  }

  return sortVillagesAlphabetically(villagesResult);
}

export function formatLocationName(rawStr: string, lang: 'te' | 'en'): string {
  if (!rawStr || typeof rawStr !== 'string') return '';
  const match = rawStr.match(/^([^(]+)(?:\(([^)]+)\))?/);
  if (!match) return rawStr.trim();

  const part1 = match[1].trim();
  const part2 = match[2] ? match[2].trim() : part1;

  let teluguPart = part1;
  let englishPart = part2;

  if (/[ఀ-౿]/.test(part2)) {
    englishPart = part1;
    teluguPart = part2;
  } else if (/[ఀ-౿]/.test(part1)) {
    teluguPart = part1;
    englishPart = part2;
  }

  return lang === 'te' ? teluguPart : englishPart;
}
